const pz = (id, title, task, lines, extra) => A.pz.push({ id, title, task, lines, extra });
pz('b01', 'Pahalı kitaplar', 'Kitap kategorisinde fiyatı 100 TL\'den yüksek ürünleri fiyata göre azalan sırala.', ['SELECT name, price', 'FROM products', "WHERE category = 'Kitap'", '  AND price > 100', 'ORDER BY price DESC;'], ["HAVING category = 'Kitap'", 'ORDER BY price;']);
pz('b02', 'Şehre göre müşteri', 'Şehri dolu olan müşterileri şehre göre say; 10\'dan fazla müşterisi olan şehirleri, sayıya göre azalan sırala.', ['SELECT city, COUNT(*) AS musteri', 'FROM customers', 'WHERE city IS NOT NULL', 'GROUP BY city', 'HAVING COUNT(*) > 10', 'ORDER BY musteri DESC;'], ['WHERE COUNT(*) > 10', 'WHERE city <> NULL']);
pz('b03', 'Departman adları', 'Çalışanların adını ve departman adını getir; departmanı olmayan çalışan da görünsün.', ['SELECT e.first_name, d.name', 'FROM employees e', 'LEFT JOIN departments d', '  ON d.dept_id = e.dept_id;'], ['JOIN departments d', 'WHERE d.dept_id IS NOT NULL']);
pz('b04', 'Kategori cirosu', 'Teslim edilen siparişlerin net cirosunu kategoriye göre topla, en yüksekten sırala.', ['SELECT p.category, ROUND(SUM(oi.quantity * oi.unit_price * (1 - oi.discount))) AS ciro', 'FROM orders o', 'JOIN order_items oi ON oi.order_id = o.order_id', 'JOIN products p ON p.product_id = oi.product_id', "WHERE o.status = 'delivered'", 'GROUP BY p.category', 'ORDER BY ciro DESC;'], ["HAVING o.status = 'delivered'", 'GROUP BY p.name']);
pz('b05', 'En pahalı üç', 'En pahalı 3 ürünün adını ve fiyatını getir.', ['SELECT name, price', 'FROM products', 'ORDER BY price DESC', 'LIMIT 3;'], ['ORDER BY price', 'WHERE ROWNUM <= 3']);
pz('b06', 'Hiç sipariş vermeyenler', 'Hiç siparişi olmayan müşterilerin numarası ve adı.', ['SELECT c.customer_id, c.first_name', 'FROM customers c', 'WHERE NOT EXISTS (', '  SELECT 1 FROM orders o', '  WHERE o.customer_id = c.customer_id', ');'], ['WHERE c.customer_id NOT IN (SELECT 1 FROM orders)', '  WHERE o.customer_id <> c.customer_id']);
pz('b07', 'Departmanın en iyisi', 'Her departmanın en yüksek maaşlı çalışanını (eşitler dahil) getir.', ['WITH s AS (', '  SELECT dept_id, first_name, salary,', '         RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS r', '  FROM employees', ')', 'SELECT dept_id, first_name, salary', 'FROM s', 'WHERE r = 1;'], ['  WHERE RANK() = 1', '         ROW_NUMBER() OVER (ORDER BY salary DESC) AS r']);
pz('b08', 'Aylık sipariş', '2024\'te her ay verilen sipariş sayısı, aya göre sıralı.', ["SELECT strftime('%Y-%m', order_date) AS ay, COUNT(*) AS siparis", 'FROM orders', "WHERE order_date >= '2024-01-01'", "  AND order_date < '2025-01-01'", "GROUP BY strftime('%Y-%m', order_date)", 'ORDER BY ay;'], ["  AND order_date <= '2024-12'", 'GROUP BY order_date']);
pz('b09', 'Yürüyen toplam', 'Aralık 2024\'ün her günü için uçuş sayısı ve ay başından itibaren kümülatif toplamı.', ['WITH g AS (', '  SELECT date(sched_dep) AS gun, COUNT(*) AS ucus', '  FROM hv_flights', "  WHERE sched_dep >= '2024-12-01'", '  GROUP BY date(sched_dep)', ')', 'SELECT gun, ucus,', '       SUM(ucus) OVER (ORDER BY gun ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS kumulatif', 'FROM g', 'ORDER BY gun;'], ['       SUM(ucus) OVER (PARTITION BY gun) AS kumulatif', '  GROUP BY sched_dep']);
pz('b10', 'Gecikme sınıfı', 'İptal edilmemiş uçuşları gecikmeye göre sınıflandırıp her sınıfta kaç uçuş olduğunu bul.', ['SELECT CASE', '         WHEN ROUND((julianday(actual_dep) - julianday(sched_dep)) * 1440) <= 15 THEN \'Zamanında\'', '         WHEN ROUND((julianday(actual_dep) - julianday(sched_dep)) * 1440) <= 60 THEN \'Gecikmeli\'', '         ELSE \'Çok gecikmeli\'', '       END AS sinif, COUNT(*) AS ucus', 'FROM hv_flights', 'WHERE actual_dep IS NOT NULL', 'GROUP BY sinif;'], ["WHERE status = NULL", "         WHEN actual_dep > sched_dep THEN 'Zamanında'"]);
pz('b11', 'Riskli müşteriler', 'Risk puanı 8 ve üzeri olan banka müşterilerini şube adlarıyla birlikte, şube adına göre sırala.', ['SELECT b.name AS sube, c.full_name, c.risk_score', 'FROM bank_customers c', 'JOIN bank_branches b ON b.branch_id = c.branch_id', 'WHERE c.risk_score >= 8', 'ORDER BY b.name, c.full_name;'], ['WHERE c.risk_score > 8', 'ON b.branch_id = c.customer_id']);
pz('b12', 'İki tablo, tek liste', 'Hem müşterilerin hem departmanların bulunduğu şehirleri tekrarsız tek liste olarak getir.', ['SELECT city FROM customers', 'WHERE city IS NOT NULL', 'UNION', 'SELECT city FROM departments;'], ['UNION ALL', 'INTERSECT']);

